    "correctCount" integer DEFAULT 0 NOT NULL,
    "incorrectCount" integer DEFAULT 0 NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "fellForTrap" boolean DEFAULT false NOT NULL,
    "lastResponse" text,
    "trapLoopActive" boolean DEFAULT false NOT NULL,
    "trapLoopCount" integer DEFAULT 0 NOT NULL,
    status public."CardMasteryStatus" DEFAULT 'UNSEEN'::public."CardMasteryStatus" NOT NULL
);


--
-- Name: UserWeakness; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."UserWeakness" (
    id text NOT NULL,
    "userId" text NOT NULL,
    "knowledgePointId" text NOT NULL,
    "incorrectCount" integer DEFAULT 0 NOT NULL,
    "totalAttempts" integer DEFAULT 0 NOT NULL,
    "lastIncorrectAt" timestamp(3) without time zone,
    "weaknessScore" double precision DEFAULT 0.0 NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL
);


--
-- Name: _prisma_migrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public._prisma_migrations (
    id character varying(36) NOT NULL,
    checksum character varying(64) NOT NULL,
    finished_at timestamp with time zone,
    migration_name character varying(255) NOT NULL,
    logs text,
    rolled_back_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_steps_count integer DEFAULT 0 NOT NULL
);


